/* Minimal self-contained HLS fallback shim for browsers without MSE (docs/DESIGN.md & PROTOCOLS). */
(function (global) {
  "use strict";

  function ScreencastHlsFallback() {}

  ScreencastHlsFallback.isSupported = function () {
    var v = document.createElement("video");
    return !!(v.canPlayType && (
      v.canPlayType("application/vnd.apple.mpegurl") !== "" ||
      v.canPlayType("application/x-mpegURL") !== ""
    ));
  };

  ScreencastHlsFallback.prototype.attach = function (videoEl, url) {
    videoEl.src = url;
    return videoEl.play();
  };

  global.ScreencastHlsFallback = ScreencastHlsFallback;
})(window);
